# Book-aligned lessons (AP Precalc Guided Notes book): 1.1-1.7 and 3.1-3.15
def L(no,title,los,vocab,diag,dans,blocks,prac,app,inv,pans,gate,gans,recap,fig=None):
    u=int(no.split('.')[0])
    std=[{'code':'LO '+c,'text':t} for c,t in los]
    return {'no':no,'unit':u,'title':title,'codes':', '.join('LO '+c for c,_ in los),'obj':[t for _,t in los],'std':std,'vocab':vocab,'recap':recap,
            'diag':{'items':diag,'done':'All answers written without a calculator, with one line of reasoning each.','ans':dans},
            'blocks':[{'title':b[0],'rules':b[1],'ex':[{'q':q,'steps':s} for q,s in b[2]],'fig':(b[3] if len(b)>3 else None),'notes':''} for b in blocks],
            'tasks':[{'k':'Practice','items':prac,'done':'Done when each answer is checked against the method in the examples.'},
                     {'k':'Apply','items':app,'done':'Done when each answer is stated in context with units or notation.'},
                     {'k':'Investigate','items':inv,'done':'Done when your explanation names the property that makes it true.'}],
            'pans':pans,'prod':None,'gate':{'items':gate,'ans':gans}}
LES=[]
A=LES.append
A(L('1.1','Change in Tandem',[('1.1.A','Describe how the input and output values of a function vary together by comparing function values.'),('1.1.B','Construct a graph representing two quantities that vary with respect to each other in a contextual scenario.')],
 ['function','domain','range','independent variable','dependent variable','increasing','decreasing','concave up','concave down','point of inflection','zero','y-intercept','VANG'],
 ['$w(x)$: $w$ is water in a pool (gallons), $x$ is the pool length. Name the input.','Is $f(a)<f(b)$ when $a<b$ the rule for increasing or decreasing?'],
 'Q1 The input (independent variable) is the length $x$. Q2 Increasing: for all $a<b$ in the interval, $f(a)<f(b)$.',
 [('Functions and VANG',['A function maps each input value to exactly one output value.','Input $=$ domain $=$ independent variable; output $=$ range $=$ dependent variable.','A rule can be given Verbally, Analytically, Numerically or Graphically (VANG).'],
   [('$h(t)$ is the height of a football $t$ seconds after it is thrown. Which variable is dependent?',['Function notation $h(t)$ puts the input inside the brackets.','So $t$ is independent and $h$ (height) is dependent.']),
    ('$b(s)$: $b$ is books in a library, $s$ is students in the school. Identify the variables.',['Dependent: $b$, the number of books.','Independent: $s$, the number of students.'])]),
  ('Increasing, decreasing and concavity',['Increasing on an interval: for all $a<b$, $f(a)<f(b)$.','Decreasing on an interval: for all $a<b$, $f(a)>f(b)$.','Concave up: rate of change increasing. Concave down: rate of change decreasing. A point of inflection is where concavity changes.'],
   [('$x$: $4,6,7,10,20$; $f(x)$: $1,1.01,1.04,1.06,1.29$. $f$ is increasing or decreasing, not both. Which, and why?',['Outputs rise as inputs rise.','$f$ is increasing on $4\\le x\\le20$, because for all $a<b$ in the interval, $f(a)<f(b)$.']),
    ('$x$: $1,2,3,4,5$; $f(x)$: $95,90,75,50,10$. Describe $f$.',['Each output is less than the one before: $f$ is decreasing.','Changes $-5,-15,-25,-40$ are decreasing, so the graph is concave down.'])])],
 ['$p(t)$: $t$ is years since kindergarten, $p$ is Pokemon cards. Name the dependent variable.','$x$: $12,16,18,25,31$; $f(x)$: $8,7.99,7.8,7.75,7.7$. Increasing or decreasing? Justify.'],
 ['The area of a circle depends on its radius. Write the function in notation and name each variable.','A graph rises and its slope gets smaller. Is it concave up or concave down?'],
 ['Explain why a straight line has no concavity, using rates of change.'],
 'Practice: dependent $p$ (cards), independent $t$ (years); decreasing, because for all $a<b$, $f(a)>f(b)$. Apply: $A(r)$, $A$ dependent, $r$ independent; concave down. Investigate: a line has a constant rate of change, so the rate neither increases nor decreases.',
 ['$c(t)$: $c$ is cups of coffee, $t$ is teachers. Name the independent variable.','$x$: $7,9,12,16,25$; $f$: $2,1.95,1.91,1.88,1.87$. Increasing or decreasing?','Where does a point of inflection occur?'],
 'Q1 $t$, the number of teachers. Q2 Decreasing on $7\\le x\\le25$: for all $a<b$, $f(a)>f(b)$. Q3 Where the graph changes concavity (the rate of change switches from increasing to decreasing or back).',
 'Inputs and outputs change in tandem: compare outputs to describe increasing or decreasing, and compare rates of change to describe concavity.'))

A(L('1.2','Rates of Change',[('1.2.A','Compare the rates of change at two points using average rates of change near the points.'),('1.2.B','Describe how two quantities vary together at different points and over different intervals of a function.')],
 ['average rate of change','slope','secant line','rate of change at a point','positive rate','negative rate','per'],
 ['Slope through $(1,2)$ and $(3,4)$?','Which goes in the numerator of a rate: input or output?'],'Q1 $\\dfrac{4-2}{3-1}=1$. Q2 The change in output.',
 [('Average rate of change',['$\\text{AROC}=\\dfrac{\\Delta y}{\\Delta x}=\\dfrac{f(b)-f(a)}{b-a}$, the slope of the secant line.','The word "per" signals a rate: the dependent quantity comes first.'],
   [('$t$: $10,13,19,25$ s; $d(t)$: $80,76,43,30$ m. AROC on $13\\le t\\le25$?',['$\\dfrac{d(25)-d(13)}{25-13}=\\dfrac{30-76}{12}$.','$=-\\dfrac{23}{6}\\approx-3.833$ meters per second.']),
    ('$h(t)=3t^{2}-t$ on $2\\le t\\le5$.',['$h(5)=70$, $h(2)=10$.','$\\dfrac{70-10}{5-2}=20$.'])]),
  ('Rate of change at a point',['Approximate the rate at $x=a$ with the AROC on a small interval containing $a$.','Positive rate: both quantities move in the same direction. Negative rate: they move in opposite directions.'],
   [('Estimate the rate of change of $f(x)=x^{2}+3x$ at $x=1$.',['Use $[1,\\,1.001]$: $\\dfrac{f(1.001)-f(1)}{0.001}$.','$\\approx5.001$, so the rate is about $5$.']),
    ('As the number of cats increases, the number of mice decreases. Sign of the rate?',['One quantity increases while the other decreases.','The rate of change is negative.'])])],
 ['$b(w)=w^{2}+2$ on $1\\le w\\le4$: AROC?','$t$: $6,12,24,48$; $d$: $20000,19800,15000,10000$. AROC on $6\\le t\\le48$.'],
 ['A candy company uses more chocolate and produces more boxes. Positive or negative rate?','Estimate the rate of change of $f(x)=2x^{3}-1$ at $x=2$ using a small interval.'],
 ['Why must a smaller interval give a better estimate of the rate at a point? Use the secant line idea.'],
 'Practice: $\\dfrac{18-3}{3}=5$; $\\dfrac{10000-20000}{42}\\approx-238.095$ follicles per month. Apply: positive; about $24$. Investigate: as the interval shrinks the secant line approaches the tangent line at the point.',
 ['AROC of $f(x)=x^{2}-2x$ on $[1,4]$?','State whether this is a positive or negative rate: more chores, happier parents.','Estimate the rate of $f(x)=\\sqrt{5x}$ at $x=1$.'],
 'Q1 $\\dfrac{8-(-1)}{3}=3$. Q2 Positive. Q3 About $1.118$.',
 'Average rate of change is the slope of a secant line, with output change on top; tiny intervals estimate the rate at a point, and the sign tells whether the quantities move together.'))

A(L('1.3','Rates of Change in Linear and Quadratic Functions',[('1.3.A','Determine the average rates of change for sections of a function.'),('1.3.B','Compare the rates of change at two points using average rates of change near the points.')],
 ['secant line','constant rate of change','consecutive equal-length intervals','rate of change of the average rate of change','concave up','concave down'],
 ['AROC of $y=2x+3$ on $[-1,4]$?','First differences of $1,4,9,16$?'],'Q1 $2$. Q2 $3,5,7$ (they change by $2$ each time).',
 [('Linear functions',['The AROC of a linear function is constant: the slope.','The rate of change of the average rates of change of a linear function is $0$.'],
   [('$y=7x+10$ on $-6\\le x\\le4$.',['AROC $=$ slope $=7$, whatever the interval.']),
    ('$x$: $-8,-4,4$; $h$: $23,17,5$; $h$ is linear. Find $h(15)$.',['Slope $=\\dfrac{17-23}{-4+8}=-\\dfrac{3}{2}$.','$h(15)=5-\\dfrac{3}{2}(11)=-\\dfrac{23}{2}$.'])]),
  ('Quadratic functions',['On consecutive equal-length intervals, the AROCs of a quadratic change at a constant rate.','Increasing AROCs: concave up. Decreasing AROCs: concave down.'],
   [('$y=x^{2}+2x$: AROC on $[1,2],[2,3],[3,4]$.',['$5,\\ 7,\\ 9$.','They increase by $2$ each time: constant change, concave up.']),
    ('A quadratic $g$ has AROC $-1$ on $[-3,0]$ and $5$ on $[0,3]$. AROC on $[3,6]$?',['The AROCs change by $6$ per interval.','Next AROC: $5+6=11$.'])])],
 ['AROC of $y=-x^{2}+4x+2$ on $-3\\le x\\le2$.','Rate of change of the AROCs of $f(x)=x^{2}-3x+8$ over intervals of length $1$.'],
 ['$x$: $15,16,17,18,19$; $g$: $18,20,20,18,14$. Concave up or down? Justify.','A quadratic has AROC $2$ on $[-1,1]$ and $7$ on $[1,3]$. AROC on $[-3,-1]$?'],
 ['Show that for $f(x)=ax^{2}+bx+c$ the AROC on $[x,x+1]$ is $a(2x+1)+b$, and explain why consecutive AROCs differ by $2a$.'],
 'Practice: $f(2)=6$ and $f(-3)=-19$, so AROC $=\\dfrac{25}{5}=5$; the AROCs change by $2$. Apply: rates $2,0,-2,-4$ decreasing, so concave down; $2-5=-3$. Investigate: $f(x+1)-f(x)=a(2x+1)+b$; moving to the next interval adds $2a$.',
 ['AROC of $y=3x-6$ on $[-3,2]$?','AROC of $y=x^{2}+3x-5$ on $[2,4]$?','Rates of change $-15,-7,-3,-1$ over equal intervals: concavity?'],
 'Q1 $3$. Q2 $9$. Q3 Increasing rates, so concave up.',
 'Linear functions keep one AROC; quadratics have AROCs that change by a constant amount, and the direction of that change gives the concavity.'))

A(L('1.4','Polynomial Functions and Rates of Change',[('1.4.A','Identify key characteristics of polynomial functions related to rates of change.')],
 ['polynomial','degree','leading term','leading coefficient','local maximum','local minimum','global (absolute) extremum','point of inflection'],
 ['Degree and leading coefficient of $3x^{2}-5x^{4}+1$?','Sign of $(-2)^{3}$?'],'Q1 Degree $4$, leading coefficient $-5$. Q2 Negative ($-8$).',
 [('Degree, extrema and zeros',['$p(x)=a_nx^{n}+\\dots+a_0$: degree $n$, leading coefficient $a_n$.','Increasing to decreasing: local maximum. Decreasing to increasing: local minimum.','Between two real zeros there is at least one local extremum.'],
   [('$f(x)=14x-6x^{3}+2x^{5}+1$: degree and leading coefficient.',['Largest exponent: $5$.','Degree $5$, leading coefficient $2$.']),
    ('$f(-2)=0$, $f(0)=5$, $f(4)=0$, $f(7)=1$. Guaranteed extrema?',['Two zeros at $x=-2$ and $x=4$.','At least one local extremum on $-2<x<4$.'])]),
  ('Global extrema and inflection',['Even degree: positive leading coefficient gives an absolute minimum, negative gives an absolute maximum.','Odd degree: no absolute extremum.','A point of inflection is where the rate of change switches from increasing to decreasing, or back.'],
   [('$f(x)=-3x^{4}+2x-5$: absolute max or min?',['Even degree, negative leading coefficient.','Absolute maximum.']),
    ('$g(x)=4(x-1)^{2}(x+3)^{3}$: absolute max or min?',['Leading term $4x^{2}\\cdot x^{3}=4x^{5}$, odd degree.','Neither.'])])],
 ['Leading coefficient and degree of $-5x^{3}+6x-x^{4}$.','$f(0)=6$, $f(3)=2$, $f(6)=0$, $f(10)=0$: guaranteed extrema?'],
 ['$L(t)=-0.56t^{3}+2.31t^{2}+0.264t+1$ for $1\\le t\\le4$ (calculator). When does $L$ change from increasing to decreasing?','$h(x)=x(6x-3)^{2}(2-x)$: absolute max, min or neither?'],
 ['Explain why a polynomial of odd degree can have no absolute maximum.'],
 'Practice: $-1$, degree $4$; yes, on $6<x<10$. Apply: about $t\\approx2.81$; leading term $-36x^{4}$, absolute maximum. Investigate: the two ends go in opposite directions without bound.',
 ['Degree and leading coefficient of $8x^{2}-6x+5$?','$f(0)=2$, $f(1)=0$, $f(11)=0$: guarantee?','$f(x)=-7x^{4}+2x+1$: absolute max or min?'],
 'Q1 Degree $2$, leading coefficient $8$. Q2 An extremum on $1<x<11$. Q3 Absolute maximum.',
 'The leading term sets degree and absolute extrema; zeros guarantee turning points between them.'))

A(L('1.5','Polynomial Functions and Complex Zeros',[('1.5.A','Identify key characteristics of a polynomial function related to its zeros when suitable factors are known or determinable.')],
 ['zero','root','linear factor','multiplicity','complex zero','non-real zero','conjugate pair','successive differences','even function','odd function'],
 ['Factor $x^{3}-2x^{2}-8x$.','Conjugate of $3-6i$?'],'Q1 $x(x-4)(x+2)$. Q2 $3+6i$.',
 [('Zeros, multiplicity and complex zeros (1.5A)',['$p(a)=0$: $a$ is a zero, $(a,0)$ is an $x$-intercept, $(x-a)$ is a factor.','Even multiplicity: the graph bounces; odd: it crosses.','Degree $n$: exactly $n$ complex zeros with multiplicity. Non-real zeros come in conjugate pairs $a\\pm bi$.','The degree equals the first level of successive differences that is constant (equal input steps).'],
   [('$p(x)=(x-2)^{3}(x+5)^{2}(x-7)$: where is $p(x)<0$?',['Zeros $-5$ (bounce), $2$, $7$.','Signs: $(-\\infty,-5)+$, $(-5,2)+$, $(2,7)-$, $(7,\\infty)+$.','$p(x)<0$ on $(2,7)$.']),
    ('Degree $8$, real zeros $10,-5,16$ with $-5$ of multiplicity $2$. Non-real zeros?',['Real zeros with multiplicity: $1+2+1=4$.','$8-4=4$ non-real zeros.'])]),
  ('Even and odd polynomials (1.5B)',['Even: $f(-x)=f(x)$, symmetric over the $y$-axis.','Odd: $f(-x)=-f(x)$, symmetric about the origin.','$p(x)=ax^{n}$: even if $n$ is even, odd if $n$ is odd.'],
   [('Show $f(x)=x^{4}-4x^{2}$ is even.',['$f(-x)=(-x)^{4}-4(-x)^{2}=x^{4}-4x^{2}=f(x)$.']),
    ('Is $f(x)=6x^{3}+2x^{2}$ even, odd or neither?',['$f(-x)=-6x^{3}+2x^{2}$.','Not $f(x)$ and not $-f(x)$: neither.'])])],
 ['$g(x)=x^{2}-17x+70$: when is $g(x)<0$?','One zero is $5+i$. Name another.'],
 ['Outputs at $x=0,\\dots,7$: $6,24,54,96,150,216,294,384$. Degree?','$g$ is odd with $g(5)=10.5$. Find $g(-5)$.'],
 ['A polynomial with real coefficients has degree $5$. Explain why it must have at least one real zero.'],
 'Practice: $(7,10)$; $5-i$. Apply: second differences constant ($12$): degree $2$; $g(-5)=-10.5$. Investigate: non-real zeros pair up, so an odd number of zeros leaves at least one real.',
 ['Degree $13$, real zeros $-9,0,13$ with $0$ of multiplicity $5$: non-real zeros?','Another zero if $-3+7i$ is a zero?','Is $f(x)=-3x^{5}+5x^{3}-2x$ even, odd or neither?'],
 'Q1 $13-7=6$. Q2 $-3-7i$. Q3 Odd.',
 'Factors give zeros and multiplicities; degree counts all complex zeros, non-real ones pair up, and symmetry is tested with $f(-x)$.'))

A(L('1.6','Polynomial Functions and End Behavior',[('1.6.A','Describe end behaviors of polynomial functions.')],
 ['end behavior','leading term','limit notation','increases without bound','decreases without bound'],
 ['Leading term of $7x^{4}-4x^{9}+8x^{2}$?','Sign of $(-10)^{5}$?'],'Q1 $-4x^{9}$. Q2 Negative.',
 [('Limit notation for the ends',['Left side: $\\lim_{x\\to-\\infty}p(x)$. Right side: $\\lim_{x\\to\\infty}p(x)$.','The leading term dominates for inputs of large magnitude.'],
   [('$p(x)=-x^{4}+x^{3}-x$.',['Even degree, negative coefficient: both ends down.','$\\lim_{x\\to-\\infty}p(x)=-\\infty$ and $\\lim_{x\\to\\infty}p(x)=-\\infty$.']),
    ('$p(x)=6x^{5}-x+1$.',['Odd degree, positive coefficient.','$\\lim_{x\\to-\\infty}p(x)=-\\infty$, $\\lim_{x\\to\\infty}p(x)=\\infty$.'])]),
  ('From factors and from statements',['Multiply the leading terms of the factors to get the leading term.','Even degree: ends match. Odd degree: ends are opposite. Sign of the leading coefficient fixes the right end.'],
   [('$f(x)=-2(x-1)^{3}(4-x)$.',['Leading term: $-2x^{3}(-x)=2x^{4}$.','Both ends up: $\\lim_{x\\to\\pm\\infty}f(x)=\\infty$.']),
    ('Sketch a polynomial with $\\lim_{x\\to-\\infty}p(x)=\\infty$ and $\\lim_{x\\to\\infty}p(x)=-\\infty$.',['Opposite ends: odd degree.','Right end down: negative leading coefficient, e.g. $p(x)=-x^{3}$.'])])],
 ['End behavior of $g(x)=4x^{3}-3x^{2}+x$.','End behavior of $f(x)=7x^{2}-8x^{5}+6$.'],
 ['$f(x)=-7x^{4}+2x+4$: which statement about its leading term and limits is true?','Write a polynomial with both ends rising and a zero at $x=3$.'],
 ['Explain why the term $3x^{2}$ cannot change the end behavior of $p(x)=-x^{5}+3x^{2}$.'],
 'Practice: $-\\infty$ left, $\\infty$ right; $\\infty$ left, $-\\infty$ right. Apply: negative, even: both limits $-\\infty$; e.g. $(x-3)^{2}$. Investigate: $\\dfrac{3x^{2}}{x^{5}}\\to0$, so $-x^{5}$ dominates.',
 ['End behavior of $p(x)=11x^{4}-6x^{2}$?','End behavior of $p(x)=-7x^{3}+4x$?','Leading term of $3(x+1)^{2}(2-x)^{3}$?'],
 'Q1 Both $\\infty$. Q2 Left $\\infty$, right $-\\infty$. Q3 $-3x^{5}$.',
 'Only the leading term matters at the ends: parity of the degree decides matching ends, the sign of its coefficient decides the right end.'))

