A(L('3.12','Equivalent Representations of Trigonometric Functions',[('3.12.A','Rewrite trigonometric expressions in equivalent forms with the Pythagorean identity.'),('3.12.B','Rewrite trigonometric expressions in equivalent forms with sine and cosine sum identities.'),('3.12.C','Solve equations using equivalent analytic representations of trigonometric functions.')],
 ['Pythagorean identity','reciprocal identity','sum identity','difference identity','double-angle identity'],
 ['$\\sin^{2}\\dfrac{\\pi}{6}+\\cos^{2}\\dfrac{\\pi}{6}$?','$\\tan x\\cos x$ in sine and cosine?'],'Q1 $1$. Q2 $\\sin x$.',
 [('Pythagorean identities (3.12A)',['$\\sin^{2}x+\\cos^{2}x=1$, $1+\\tan^{2}x=\\sec^{2}x$, $1+\\cot^{2}x=\\csc^{2}x$.','Rewrite in $\\sin$ and $\\cos$, replace squares, then simplify.'],
   [('$\\dfrac{1-\\cos^{2}x}{\\sin x}$',['$1-\\cos^{2}x=\\sin^{2}x$.','$\\dfrac{\\sin^{2}x}{\\sin x}=\\sin x$.']),
    ('Solve $1-\\sin^{2}x+\\cos^{2}x=2$ on $[0,2\\pi]$.',['$2\\cos^{2}x=2$, $\\cos x=\\pm1$.','$x=0,\\ \\pi,\\ 2\\pi$.'])]),
  ('Sum, difference and double angle (3.12B)',['$\\sin(\\alpha\\pm\\beta)=\\sin\\alpha\\cos\\beta\\pm\\cos\\alpha\\sin\\beta$.','$\\cos(\\alpha\\pm\\beta)=\\cos\\alpha\\cos\\beta\\mp\\sin\\alpha\\sin\\beta$.','$\\sin2\\alpha=2\\sin\\alpha\\cos\\alpha$; $\\cos2\\alpha=\\cos^{2}\\alpha-\\sin^{2}\\alpha$.'],
   [('$\\sin\\left(\\dfrac{\\pi}{4}+\\dfrac{\\pi}{3}\\right)$',['$\\dfrac{\\sqrt2}{2}\\cdot\\dfrac12+\\dfrac{\\sqrt2}{2}\\cdot\\dfrac{\\sqrt3}{2}$.','$=\\dfrac{\\sqrt2+\\sqrt6}{4}$.']),
    ('Solve $\\sin2x=\\cos x$ on $[0,2\\pi)$.',['$\\cos x(2\\sin x-1)=0$.','$x=\\dfrac{\\pi}{2},\\dfrac{3\\pi}{2},\\dfrac{\\pi}{6},\\dfrac{5\\pi}{6}$.'])])],
 ['Simplify $\\cot x\\sin x$.','Simplify $\\dfrac{\\sec^{2}x-1}{\\sin^{2}x}$.'],
 ['$\\cos\\left(\\dfrac{7\\pi}{4}-\\dfrac{2\\pi}{3}\\right)$ exactly.','Solve $\\cos2x=\\cos x$ on $[0,2\\pi)$.'],
 ['Derive $\\cos2\\alpha=1-2\\sin^{2}\\alpha$ from $\\cos2\\alpha=\\cos^{2}\\alpha-\\sin^{2}\\alpha$.'],
 'Practice: $\\cos x$; $\\sec^{2}x$. Apply: $\\cos\\dfrac{13\\pi}{12}=-\\dfrac{\\sqrt6+\\sqrt2}{4}$; $x=0,\\dfrac{2\\pi}{3},\\dfrac{4\\pi}{3}$. Investigate: replace $\\cos^{2}\\alpha$ with $1-\\sin^{2}\\alpha$.',
 ['Simplify $\\sin\\theta\\sec\\theta$.','$\\sin\\left(\\dfrac{\\pi}{3}-\\dfrac{\\pi}{4}\\right)$?','$\\cos2\\theta$ if $\\sin\\theta=\\dfrac35$?'],
 'Q1 $\\tan\\theta$. Q2 $\\dfrac{\\sqrt6-\\sqrt2}{4}$. Q3 $\\dfrac{7}{25}$.',
 'Rewrite in sine and cosine, use the Pythagorean, sum or double-angle identity that fits, and factor to solve.'))

A(L('3.13','Trigonometry and Polar Coordinates',[('3.13.A','Determine the location of a point in the plane using both rectangular and polar coordinates.'),('3.13.B','Represent complex numbers in the complex plane.')],
 ['polar coordinates','pole','polar axis','rectangular coordinates','complex plane','modulus','argument','polar form'],
 ['$\\sqrt{3^{2}+4^{2}}$?','$\\cos\\dfrac{2\\pi}{3}$?'],'Q1 $5$. Q2 $-\\dfrac12$.',
 [('Polar and rectangular',['$(r,\\theta)$: distance $r$ from the pole at angle $\\theta$.','$x=r\\cos\\theta$, $y=r\\sin\\theta$; $r=\\sqrt{x^{2}+y^{2}}$, $\\tan\\theta=\\dfrac{y}{x}$ (check the quadrant).','$(r,\\theta)$, $(r,\\theta+2\\pi)$ and $(-r,\\theta+\\pi)$ name the same point.'],
   [('$\\left(4,\\dfrac{2\\pi}{3}\\right)$ to rectangular.',['$x=4\\cos\\dfrac{2\\pi}{3}=-2$, $y=4\\sin\\dfrac{2\\pi}{3}=2\\sqrt3$.']),
    ('$(-3,4)$ to polar, $0\\le\\theta<2\\pi$.',['$r=5$.','Quadrant II: $\\theta=\\pi-\\tan^{-1}\\dfrac43\\approx2.214$.'])]),
  ('Complex numbers in polar form',['$z=a+bi$ is the point $(a,b)$; $|z|=\\sqrt{a^{2}+b^{2}}$.','$z=r(\\cos\\theta+i\\sin\\theta)$.'],
   [('$3+4i$ in polar form.',['$r=5$, $\\theta=\\tan^{-1}\\dfrac43\\approx0.927$.','$5(\\cos0.927+i\\sin0.927)$.']),
    ('$4\\left(\\cos\\dfrac{3\\pi}{2}+i\\sin\\dfrac{3\\pi}{2}\\right)$ in rectangular form.',['$4(0)+4(-1)i$.','$-4i$.'])])],
 ['$\\left(2,\\dfrac{\\pi}{4}\\right)$ to rectangular.','$(2,-4)$ to polar.'],
 ['$-3+3i$ in polar form.','Name $\\left(3,\\dfrac{\\pi}{6}\\right)$ with a negative $r$.'],
 ['Explain why $\\tan^{-1}\\dfrac{y}{x}$ alone can give the wrong angle for $(-3,-4)$.'],
 'Practice: $(\\sqrt2,\\sqrt2)$; $(2\\sqrt5,\\ 5.176)$. Apply: $3\\sqrt2\\left(\\cos\\dfrac{3\\pi}{4}+i\\sin\\dfrac{3\\pi}{4}\\right)$; $\\left(-3,\\dfrac{7\\pi}{6}\\right)$. Investigate: $\\tan^{-1}\\dfrac43$ is in quadrant I, but the point is in quadrant III: add $\\pi$.',
 ['$\\left(6,\\dfrac{\\pi}{3}\\right)$ to rectangular?','$|2-5i|$?','$(0,-7)$ to polar?'],
 'Q1 $(3,3\\sqrt3)$. Q2 $\\sqrt{29}$. Q3 $\\left(7,\\dfrac{3\\pi}{2}\\right)$.',
 'Polar and rectangular forms convert with $x=r\\cos\\theta$, $y=r\\sin\\theta$; the same rules write complex numbers in polar form.'))

